<?php
require __DIR__.'/config.php';require_role(['admin','teacher']);$docs=read_json('documents');$dir=PRIVATE_DIR.'/documents';if(!is_dir($dir))mkdir($dir,0700,true);
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(!empty($_FILES['file']['tmp_name'])&&is_uploaded_file($_FILES['file']['tmp_name'])){$orig=$_FILES['file']['name'];$ext=strtolower(pathinfo($orig,PATHINFO_EXTENSION));$allowed=['pdf','doc','docx','xls','xlsx','png','jpg','jpeg'];if(!in_array($ext,$allowed,true)){flash('File type not allowed.');}elseif($_FILES['file']['size']>10*1024*1024){flash('Maximum file size is 10 MB.');}else{$id=next_id($docs);$name=$id.'_'.bin2hex(random_bytes(8)).'.'.$ext;move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$name);$docs[]=['id'=>$id,'title'=>trim($_POST['title']),'original_name'=>$orig,'filename'=>$name,'audience'=>$_POST['audience'],'uploaded_by'=>current_user()['id'],'created_at'=>date('c')];write_json('documents',$docs);log_action('upload','document',$id);flash('Document uploaded.');}}redirect('documents.php');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Documents</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1100px;margin:auto;padding:28px}.card{background:#fff;border:1px solid #ddd;border-radius:14px;padding:20px;margin-bottom:18px}input,select{width:100%;box-sizing:border-box;margin:6px 0 12px}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="index.php">← Dashboard</a></p><h1>Document Manager</h1><div class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Title<input name="title" required></label><label>Audience<select name="audience"><option>All</option><option>Students</option><option>Parents</option><option>Teachers</option></select></label><label>File<input type="file" name="file" required></label><button>Upload document</button></form></div><div class="card"><h2>Uploaded documents</h2><?php foreach(array_reverse($docs) as $d):?><p><strong><?=h($d['title'])?></strong> — <?=h($d['original_name'])?> <span><?=h($d['audience'])?></span></p><?php endforeach;?></div></div><script src="assets/dynamic-site.js"></script>
</body></html>